verificationView=()=>{if(!verification)return '<section class="panel empty">正在读取发布证据…</section>';const channels=[['facebook','Facebook'],['xiaohongshu','小红书'],['wechat_official_account','微信公众号'],['wechat_channels','视频号']],rows=verification.rows.filter(x=>(!verificationPlatform||x.platform===verificationPlatform)&&(!verificationStatus||x.verification_status===verificationStatus)&&(!verificationQuery||`${x.article_id} ${x.title}`.toLowerCase().includes(verificationQuery.toLowerCase()))),s=verification.summary;const inventory=wechatInventory?`<div class="twocol"><section class="inventory"><h3>公众号已发表 ${wechatInventory.published.length} 篇</h3>${wechatInventory.published.slice(0,20).map(x=>`<div class="inventory-item"><b>${esc(x.title||'无标题')}</b><small>${esc(x.updated_at||'')}</small>${x.url?`<a href="${esc(x.url)}" target="_blank">打开文章</a>`:''}</div>`).join('')||'<p class="empty">已发表列表为空</p>'}</section><section class="inventory"><h3>公众号草稿箱 ${wechatInventory.drafts.length} 篇</h3>${wechatInventory.drafts.slice(0,20).map(x=>`<div class="inventory-item"><b>${esc(x.title||'无标题')}</b><small>${esc(x.updated_at||'')}</small></div>`).join('')||'<p class="empty">草稿箱为空</p>'}</section></div>`:'';const browser=wechatBrowserStatus?`<div class="inline-status ${wechatBrowserStatus.loggedIn?'success':''}">${esc(wechatBrowserStatus.message)}</div>`:'';return `<div class="grid"><div class="metric">已确认发布<strong>${s.published}</strong></div><div class="metric">公众号草稿<strong>${s.drafts}</strong></div><div class="metric">待核对<strong>${s.pending}</strong></div><div class="metric">未确认发布<strong>${s.not_published}</strong></div></div><section class="panel"><h2>公众号后台只读校验</h2><p>自动遍历“发表记录”和“草稿箱”的全部分页，并用真实标题与链接更新校验状态。首次需要扫码一次；只读取，不发表、不删除。</p>${browser}<div class="channel-actions"><button id="launch-wechat-browser">打开公众号后台</button><button id="read-wechat-browser">全量读取并更新状态</button></div></section><section class="panel"><h2>按渠道读取最新内容</h2><p>选择一个渠道后手工刷新。微信公众号会同时读取官方“已发表”和“草稿箱”列表；其他渠道会核对该渠道所有待确认任务，不会发布或重发。</p><div class="channel-actions">${channels.map(([id,name])=>`<button data-refresh-channel="${id}">${name} · 刷新校验</button>`).join('')}</div>${inventory}</section><section class="panel"><div class="panelhead"><div><h2>按内容校验</h2><p>搜索内容后，可只刷新这一篇在对应渠道的发布状态。</p></div><button id="refresh-verification">刷新本地记录</button></div><div class="verification-filters"><input id="verification-search" value="${esc(verificationQuery)}" placeholder="搜索内容编号或标题"><select id="verification-platform"><option value="">全部平台</option>${channels.map(([v,n])=>`<option value="${v}" ${verificationPlatform===v?'selected':''}>${n}</option>`).join('')}</select><select id="verification-status"><option value="">全部结果</option>${[['VERIFIED_PUBLISHED','已确认发布'],['VERIFIED_DRAFT','已确认草稿'],['RECONCILE_PENDING','待平台核对'],['NOT_PUBLISHED','未确认发布'],['VERIFIED_DELETED','已确认删除']].map(([v,n])=>`<option value="${v}" ${verificationStatus===v?'selected':''}>${n}</option>`).join('')}</select></div><p class="hint">显示 ${rows.length} / ${verification.rows.length} 条 · 最近读取 ${esc(verification.checked_at)}</p><div class="verification-list">${rows.map(x=>`<article class="verification-row"><div><b>${esc(x.article_id)} · ${esc(x.title)}</b><small>${esc(x.platform_name)} · ${esc(x.account_id)}</small></div><div><span class="verify ${x.verification_status.toLowerCase()}">${esc(x.label)}</span><small>${esc(x.detail)}${x.last_verified_at?' · '+esc(x.last_verified_at):''}</small></div><div>${x.platform_url?`<a href="${esc(x.platform_url)}" target="_blank">打开平台内容</a>`:''}<button data-refresh-content="${x.article_id}" data-platform="${x.platform}">刷新这篇</button></div></article>`).join('')||'<div class="empty">当前筛选没有记录。</div>'}</div></section>`};
document.addEventListener('click',e=>{const button=e.target.closest('[data-route="verification"]');if(!button)return;e.preventDefault();e.stopImmediatePropagation();route='verification';message='';verification=null;load()},true);
document.addEventListener('input',e=>{if(e.target.id!=='verification-search')return;verificationQuery=e.target.value;render();const input=document.getElementById('verification-search');input?.focus();input?.setSelectionRange(input.value.length,input.value.length)});
document.addEventListener('change',e=>{if(e.target.id==='verification-platform'){verificationPlatform=e.target.value;render()}if(e.target.id==='verification-status'){verificationStatus=e.target.value;render()}});
document.addEventListener('click',async e=>{if(e.target.id==='refresh-verification'){e.target.disabled=true;try{verification=await get('/api/publication-verification');message='已刷新本地账本和现有平台回读证据';render()}catch(error){message=error.message;render()}return}const button=e.target.closest('[data-verify-job]');if(!button)return;button.disabled=true;button.textContent='正在读取平台…';try{const value=await request('/api/publication-verification/verify',{job_id:button.dataset.verifyJob});verification=value.report;message='平台核对已完成；全程没有发布或重发';render()}catch(error){message=error.message;render()}});
document.addEventListener('click',async e=>{const channel=e.target.closest('[data-refresh-channel]'),content=e.target.closest('[data-refresh-content]');if(!channel&&!content)return;const button=channel||content,platform=channel?.dataset.refreshChannel||content.dataset.platform,article_id=content?.dataset.refreshContent||'';button.disabled=true;button.textContent='正在读取平台…';try{const value=await request('/api/publication-verification/refresh-platform',{platform,article_id});verification=value.report;if(value.inventory)wechatInventory=value.inventory;const failed=value.results.filter(x=>!x.ok).length;message=article_id?`已刷新 ${article_id} 在该渠道的状态：核对 ${value.attempted} 条${failed?`，${failed} 条读取失败`:''}`:`渠道刷新完成：核对 ${value.attempted} 条待确认任务${value.inventory?'，并读取公众号已发表和草稿箱':''}${failed?`；${failed} 条读取失败`:''}`;render()}catch(error){message=error.message;render()}});
document.addEventListener('click',async e=>{if(!['launch-wechat-browser','read-wechat-browser'].includes(e.target.id))return;const button=e.target;button.disabled=true;try{const value=await request(`/api/publication-verification/wechat-browser/${button.id==='launch-wechat-browser'?'launch':'read'}`);wechatBrowserStatus=value.status||value;if(value.items)wechatInventory={published:value.items.filter(x=>x.channel==='published'),drafts:value.items.filter(x=>x.channel==='draft'),content_data:[],published_error:null,drafts_error:null,content_data_error:null};if(value.report)verification=value.report;const r=value.reconciliation;message=wechatBrowserStatus.loggedIn?`公众号全量对账完成：已发表 ${wechatInventory?.published.length||0} 篇、草稿 ${wechatInventory?.drafts.length||0} 篇；匹配资料库 ${r?.matched||0} 篇，账本新增 ${r?.ledgerUpdated||0} 条，任务状态更新 ${r?.jobsUpdated||0} 条`:'公众号专用窗口已打开，请在该窗口扫码登录，然后点“全量读取并更新状态”';render()}catch(error){message=error.message;render()}});
new MutationObserver(()=>{ensureAccountImport();ensureAccountDefaults();ensureAuthorizationActions();ensureRadarControls();ensureVerificationTitle()}).observe(document.getElementById('app'),{childList:true,subtree:true});
load();
async function checkGptUpdates(manual=false){
  if(!workspace||gptUpdateBusy)return;
  const target=workspace;gptUpdateBusy=true;
  if(manual)render();
  try{
    const result=await get('/api/group-library?refresh=1&workspace='+encodeURIComponent(target));
    if(workspace!==target)return;
    libraryItems=result.items;libraryWorkspace=target;
    const available=new Set(result.items.filter(item=>item.ready!==false).map(item=>item.key));
    libraryPicked=new Set([...libraryPicked].filter(key=>available.has(key)));
    gptUpdateWorkspace=target;gptUpdateCheckedAt=new Date().toLocaleString();gptUpdateError='';
    if(manual)message='已读取当前投稿目录中的最新稿件；待审核内容已更新';
  }catch(error){
    if(workspace===target){gptUpdateWorkspace=target;gptUpdateError=error.message;if(manual)message='更新失败：'+error.message;}
  }finally{gptUpdateBusy=false;if(workspace===target&&route==='groups')render();}
}
setInterval(()=>{if(route==='groups'&&workspace&&document.visibilityState!=='hidden')checkGptUpdates()},20000);
